referenceSolutions.python:
def bitRibbonsFirstQualifyingSlip(readings, k):
    a=readings
    out=[]
    for x in a:
        count=0
        while x:
            x&=x-1
            count+=1
        out.append(count)
    return next((x for x in out if x>=k),-1)

